<template>
  <AuthLayout :loading="processing" :showInfoPanel="false">
    <AuthCard
      :title="isSwitchMode ? $t('org_switcher_header') : $t('org_picker_title')"
      :subtitle="isSwitchMode ? '' : $t('org_picker_subtitle')"
      :error="errorMessage ? errorMessage : ''"
      :dismissible-error="true"
      @dismiss-error="errorMessage = ''"
    >
      <!-- Filter (DOCB-13836): only for users with enough orgs that scrolling
           alone gets tedious. Below the threshold it would be pure noise —
           and it keeps the M1/M2 Playwright specs (2-3 org fixtures) on the
           plain list they assert against. Purely client-side: the full list
           is already in memory (no pagination on
           GET /v2/users/me/organisations). -->
      <q-input
        v-if="showSearch"
        v-model="search"
        outlined
        dense
        clearable
        color="primary"
        class="org-picker-search"
        data-test="org-picker-search"
        :label="$t('org_picker_search_placeholder')"
      >
        <template #append>
          <q-icon name="search" />
        </template>
      </q-input>

      <q-list class="org-picker-list" data-test="org-picker-list">
        <q-item
          v-for="org in filteredOrganisations"
          :key="org.org_id"
          clickable
          v-ripple
          tag="label"
          :class="{ 'org-picker-item--selected': selectedOrgId === org.org_id }"
          class="org-picker-item"
          :data-test="'org-picker-item-' + org.org_id"
          @click="selectedOrgId = org.org_id"
        >
          <q-item-section avatar class="org-picker-item-radio">
            <q-radio v-model="selectedOrgId" :val="org.org_id" color="primary" />
          </q-item-section>
          <q-item-section avatar class="org-picker-item-avatar">
            <q-avatar size="32px" class="user-avatar-background">
              <span class="user-item-initials org-picker-item-initials">{{ getInitials(org.name) }}</span>
            </q-avatar>
          </q-item-section>
          <q-item-section class="org-picker-item-main">
            <span class="org-picker-item-name" data-test="org-picker-name">{{ org.name }}</span>
            <span class="org-picker-item-role text-muted-foreground">{{ roleLabel(org) }}</span>
          </q-item-section>
          <q-item-section side top>
            <div class="row items-center no-wrap q-gutter-xs">
              <q-badge
                v-if="org.region"
                outline
                color="primary"
                data-test="org-picker-item-region"
              >{{ org.region.toUpperCase() }}</q-badge>
              <q-badge
                v-if="org.is_supplier"
                outline
                color="grey-7"
                data-test="org-picker-item-supplier"
              >{{ $t('org_picker_role_supplier') }}</q-badge>
            </div>
          </q-item-section>
        </q-item>
      </q-list>

      <div
        v-if="showSearch && !filteredOrganisations.length"
        class="org-picker-empty text-muted-foreground"
        data-test="org-picker-no-results"
      >
        {{ $t('org_picker_search_no_results') }}
      </div>

      <!-- The submit button acts on selectedOrgId, which deliberately SURVIVES
           filtering (a filter is not a deselection). Without this line the user
           could type a filter, no longer see their selection, and submit into an
           org they can't see on screen. -->
      <div
        v-if="hiddenSelectionName"
        class="org-picker-hidden-selection text-muted-foreground"
        data-test="org-picker-hidden-selection"
      >
        {{ $t('org_picker_selection_hidden', { name: hiddenSelectionName }) }}
      </div>

      <q-checkbox
        v-if="!isSwitchMode"
        v-model="setAsDefault"
        :label="$t('org_picker_set_default')"
        color="primary"
        dense
        class="q-mt-md"
        data-test="org-picker-set-default-checkbox"
      />

      <template #actions>
        <q-btn
          unelevated
          color="primary"
          text-color="white"
          :disable="!selectedOrgId || processing"
          :label="isSwitchMode ? $t('org_picker_submit_switch') : $t('org_picker_submit')"
          class="auth-submit-btn"
          data-test="org-picker-submit-button"
          @click="onSubmit()"
        />
      </template>
    </AuthCard>

    <template #footer>
      <a
        v-if="isSwitchMode"
        class="text-primary cursor-pointer hover:underline text-sm"
        data-test="org-picker-cancel-switch-link"
        @click="onCancelSwitch()"
      >
        {{ $t('cancel') }}
      </a>
      <a
        v-else
        class="text-primary cursor-pointer hover:underline text-sm"
        data-test="org-picker-other-account-link"
        @click="onUseOtherAccount()"
      >
        {{ $t('org_picker_other_account') }}
      </a>
    </template>
  </AuthLayout>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { AuthLayout, AuthCard } from 'src/components/Auth';
import { LocalStorage, SessionStorage } from 'quasar';
import { useAuthTokenStore } from 'src/store/main';
import { userApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { AppVersion } from 'src/utils/app_version';
import {
  takeOrgSelectionPending,
  type OrgSelectionPending,
} from 'src/utils/organization/org-selection-pending';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import type { MeOrganisationItem } from 'src/sdk/auth/models';
import type { dynamicObj } from 'src/pages/assets';

// Above this many orgs the bounded scroll list stops being scannable and the
// filter input appears (DOCB-13836). Deliberately above the 2-3 org fixtures
// the multi-org Playwright specs use, so those keep asserting the plain list.
const SEARCH_THRESHOLD = 8;

// Multi-Org Login step 2 (M1, SD 2860679170 §4.1): the auth service withheld
// the full token in step 1 (org_selection_required) — this screen exchanges
// the short-lived selection_token + the user's chosen org_id for it via
// POST /v2/oauth2/select-org.
//
// It also doubles as the Multi-Org SWITCH screen (M2, SD §4.2, PO
// correction DOCB-13399): reached via the header's HeaderOrgSwitchButton.vue
// (?mode=switch) for an ALREADY-authenticated user. The PO's final spec is
// explicit that this must be the exact same picker UI as the login flow —
// no separate inline dropdown — so both modes share this one component.
// "isSwitchMode" branches the two places the flows actually differ: where
// the org list comes from (pending selection_token handoff vs.
// getMyOrganisations()) and which token call finalizes the choice
// (select-org vs. switch-org).
export default defineComponent({
  name: 'OrgPicker',
  components: { AuthLayout, AuthCard },
  data() {
    return {
      pending: null as OrgSelectionPending | null,
      organisations: [] as MeOrganisationItem[],
      selectedOrgId: '' as string,
      setAsDefault: false,
      processing: false,
      errorMessage: '',
      isSwitchMode: false,
      search: '' as string,
    };
  },
  computed: {
    // Threshold, not "always on": with a handful of orgs the list is faster to
    // scan than to type into (DOCB-13836).
    showSearch(): boolean {
      return this.organisations.length > SEARCH_THRESHOLD;
    },
    filteredOrganisations(): MeOrganisationItem[] {
      // q-input with `clearable` writes null (not '') on clear.
      const term = (this.search ?? '').trim().toLowerCase();
      if (!term) return this.organisations;
      return this.organisations.filter((org) => {
        const name = (org.name ?? '').toLowerCase();
        const region = (org.region ?? '').toLowerCase();
        return name.includes(term) || region.includes(term);
      });
    },
    // Non-empty only while the current selection is filtered OUT of view —
    // drives the "your pick is hidden" hint next to the submit button.
    hiddenSelectionName(): string {
      if (!this.selectedOrgId) return '';
      if (this.filteredOrganisations.some((org) => org.org_id === this.selectedOrgId)) return '';
      const selected = this.organisations.find((org) => org.org_id === this.selectedOrgId);
      return selected?.name ?? '';
    },
  },
  mounted() {
    this.isSwitchMode = this.$route.query.mode === 'switch';
    if (this.isSwitchMode) {
      this.initSwitchMode();
      return;
    }
    this.pending = takeOrgSelectionPending();
    if (!this.pending || !this.pending.organisations?.length) {
      // Direct navigation without a pending selection (refresh, bookmark,
      // back-button after the token already expired) — nothing to pick from.
      this.$router.replace('/login');
      return;
    }
    this.organisations = this.pending.organisations;
    // Mirrors M1's mockup: the current default (if any) is preselected,
    // otherwise the first org — the user still has to press "Einloggen"
    // (SD §4.1: no full token before an explicit choice).
    const defaultOrg = this.organisations.find((o) => o.is_default);
    this.selectedOrgId = (defaultOrg ?? this.organisations[0]).org_id;
    this.scrollSelectedIntoView();
  },
  methods: {
    // The list is a bounded scroll container (DOCB-13836): a preselected org
    // further down would otherwise sit outside the visible window on arrival,
    // making it look like nothing is selected.
    scrollSelectedIntoView() {
      void this.$nextTick(() => {
        const items = this.$el?.querySelectorAll?.('[data-test^="org-picker-item-"]');
        if (!items) return;
        const target = Array.from(items as NodeListOf<HTMLElement>).find(
          (el) => el.getAttribute('data-test') === `org-picker-item-${this.selectedOrgId}`,
        );
        target?.scrollIntoView?.({ block: 'nearest' });
      });
    },
    async initSwitchMode() {
      const auth_token_store = useAuthTokenStore();
      if (auth_token_store.isTokenExpired()) {
        // Direct/stale navigation without a live session (e.g. a bookmarked
        // switch link after logout) — nothing to switch FROM.
        this.$router.replace('/login');
        return;
      }
      try {
        const response = await userApiService.getMyOrganisations();
        this.organisations = response?.organisations ?? [];
        if (this.organisations.length < 2) {
          // Nothing to switch to (single-org user, or membership changed
          // since the header icon was rendered) — bounce back rather than
          // show a pointless single-item picker.
          this.$router.replace('/dashboard');
          return;
        }
        // Unlike the login flow (which preselects the DEFAULT org), the
        // switch flow preselects the CURRENTLY ACTIVE org — the user is
        // already working in one of these.
        const activeOrgId = getOrgId();
        const activeOrg = this.organisations.find((o) => o.org_id === activeOrgId);
        this.selectedOrgId = (activeOrg ?? this.organisations[0]).org_id;
        this.scrollSelectedIntoView();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        this.errorMessage = (msg as string) || (this.$t('org_picker_error') as string);
      }
    },
    getInitials(fullname: string): string {
      const names = (fullname || '').trim().split(/\s+/);
      let initials = (names[0]?.substring(0, 1) || '').toUpperCase();
      if (names.length > 1) {
        initials += names[names.length - 1].substring(0, 1).toUpperCase();
      }
      return initials;
    },
    roleLabel(org: MeOrganisationItem): string {
      if (org.is_organisation_admin) {
        return this.$t('org_picker_role_admin') as string;
      }
      if (org.is_supplier) {
        return this.$t('org_picker_role_supplier_access') as string;
      }
      return this.$t('org_picker_role_member') as string;
    },
    onUseOtherAccount() {
      this.$router.replace('/login');
    },
    onCancelSwitch() {
      this.$router.push('/dashboard');
    },
    async onSubmit() {
      if (!this.selectedOrgId) return;
      if (this.isSwitchMode) {
        await this.onSubmitSwitch();
        return;
      }
      if (!this.pending) return;
      this.processing = true;
      this.errorMessage = '';
      try {
        const auth_token_store = useAuthTokenStore();

        // select-org goes through the SAME token-injecting request
        // interceptor as every other authenticated call (isTokenEndpoint in
        // auth-axios-instance.ts only exempts /oauth2/token) — it can itself
        // trigger a refresh, which acquires the 'docbits-token-refresh' Web
        // Lock (refreshAcrossTabs in auth_token.store.ts). Web Locks are NOT
        // reentrant, so the network call must stay OUTSIDE that lock or a
        // refresh racing with select-org deadlocks (2nd Codex-review pass
        // caught an earlier version of this fix that wrapped the network
        // call too — see commit history).
        const tokenInfo = await userApiService.selectOrganisation(
          this.pending.selectionToken,
          this.selectedOrgId,
          this.setAsDefault,
        );

        // Only the LocalStorage/SessionStorage WRITES are lock-protected —
        // same cross-tab mutex as UserDropDown.vue#onSwitchOrg: guards
        // against a concurrent silent refresh in another tab of this
        // browser (e.g. a still-logged-in session) landing its write after
        // ours and resurrecting a stale token.
        const applyWrite = async () => {
          auth_token_store.setTokenInLocalStorage(tokenInfo);
          await auth_token_store.setAuthToken(tokenInfo.access_token);
          // Seed active_org_id BEFORE navigating — same reasoning as
          // UserDropDown.vue#onSwitchOrg: prepare-dashboard's region
          // reconciliation (regionFromOrgs, SD Befund B8) and the X-ORG-ID
          // interceptor must resolve to the org just picked, not a stale
          // value from a previous session, and setUserSession() doesn't run
          // until AFTER reconcileRegion() in PrepareDashboard.vue.
          SessionStorage.set('active_org_id', String(tokenInfo.org_id));
        };
        const locks = typeof navigator !== 'undefined' ? navigator.locks : undefined;
        if (locks && typeof locks.request === 'function') {
          await locks.request('docbits-token-refresh', applyWrite);
        } else {
          await applyWrite();
        }

        AppVersion.updateVersion();
        LocalStorage.remove('selectedSubOrg');
        LocalStorage.remove('intentional_logout');

        const redirectUrl = this.pending.redirect
          ? `/prepare-dashboard?redirect=${this.pending.redirect}`
          : '/prepare-dashboard';

        if (this.pending.forceFullReload) {
          window.location.href = redirectUrl;
          return;
        }
        this.$router.push(redirectUrl);
      } catch (err) {
        // Expired/reused selection_token (SD §7: single-use, TTL 300s) or a
        // membership that was revoked between step 1 and step 2 — both are
        // fatal to this flow, there is no partial-retry path.
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        this.errorMessage = (msg as string) || (this.$t('org_picker_error') as string);
      } finally {
        this.processing = false;
      }
    },

    // Switch-mode counterpart of onSubmit() above: the already-authenticated
    // user picked a DIFFERENT org to switch into. This reuses the exact
    // switch-org token-exchange logic that used to live in
    // UserDropDown.vue#onSwitchOrg (see that method's history for why the
    // network call must stay OUTSIDE the 'docbits-token-refresh' Web Lock —
    // Web Locks are not reentrant — while only the storage WRITES are
    // lock-protected against a concurrent silent refresh in another tab).
    async onSubmitSwitch() {
      this.processing = true;
      this.errorMessage = '';
      try {
        const auth_token_store = useAuthTokenStore();
        const tokenInfo = await userApiService.switchOrganisation(this.selectedOrgId);

        const applyWrite = async () => {
          auth_token_store.setTokenInLocalStorage(tokenInfo);
          // Seed active_org_id BEFORE navigating — prepare-dashboard's region
          // reconciliation (region-sync.ts) and the X-ORG-ID interceptor both
          // resolve to the NEW org immediately (same reasoning as the
          // now-removed UserDropDown.vue#onSwitchOrg).
          SessionStorage.set('active_org_id', String(tokenInfo.org_id));
        };
        const locks = typeof navigator !== 'undefined' ? navigator.locks : undefined;
        if (locks && typeof locks.request === 'function') {
          await locks.request('docbits-token-refresh', applyWrite);
        } else {
          await applyWrite();
        }

        // A sub-org selection from the PREVIOUS org has no meaning in the new one.
        LocalStorage.remove('selectedSubOrg');

        // Hard navigation (not router.push): switching org needs the same
        // full re-init pipeline as a fresh login (profile reload, region
        // reconciliation, store resets) — prepare-dashboard already owns
        // exactly that sequence.
        window.location.href = '/prepare-dashboard';
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        this.errorMessage = (msg as string) || (this.$t('org_picker_error') as string);
      } finally {
        this.processing = false;
      }
    },
  },
});
</script>

<style scoped lang="scss">
/* DOCB-13836: the list MUST own its scrolling.
   AuthLayout's `.auth-panel { overflow-y: auto }` never engages, because its
   parent `.auth-page` is sized with `min-height: 100vh` — a min-height puts a
   floor under the box but no ceiling, so the panel simply grows with its
   content and never overflows. With ~28 orgs the card therefore grew past the
   viewport and pushed the submit button below the fold.
   The ceiling below reserves ~420px for the surrounding chrome (panel padding,
   logo header, title, search field, default-checkbox, action button, footer)
   so the button stays reachable without scrolling the document; the floor
   keeps at least ~3 rows visible on very short viewports. */
.org-picker-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: clamp(180px, calc(100vh - 420px), 480px);
  overflow-y: auto;
  /* Don't hand the wheel over to the document once the list hits its end. */
  overscroll-behavior: contain;
  /* Room for the scrollbar so it never overlaps the region/supplier badges. */
  padding-right: 4px;
}

.org-picker-search {
  margin-bottom: 4px;
}

.org-picker-empty,
.org-picker-hidden-selection {
  font-size: 13px;
  padding: 8px 2px 0;
}

.org-picker-item {
  /* The list is a height-bounded flex column; without this the items shrink
     to q-item's min-height and multi-line names bleed past the row borders. */
  flex-shrink: 0;
  border: 1px solid var(--border);
  border-radius: 8px;
}

.org-picker-item--selected {
  border-color: var(--primary);
  background: color-mix(in srgb, var(--primary) 8%, transparent);
}

/* Quasar's QItemSection carries its `.column` utility class, which sets
   flex-wrap: wrap. When the name and role outgrow the row height they wrap
   into a SECOND column that collides with the badges and forces the list to
   scroll horizontally. */
.org-picker-item-main {
  flex-wrap: nowrap;
  gap: 2px;
}

/* Quasar reserves min-width: 56px per avatar section; with the radio and the
   32px avatar both counting as one, the text lost ~60px of card width. */
.org-picker-item-radio {
  min-width: 0;
  padding-right: 4px;
}

.org-picker-item-avatar {
  min-width: 0;
  padding-right: 12px;
}

.org-picker-item-name {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

/* The global .user-item-initials is sized for 40px avatars (26px font). */
.org-picker-item-initials {
  font-size: 13px;
}

.org-picker-item-role {
  font-size: 12px;
}
</style>
